// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint96 blockNumber, uint64 timestamp) public {
        vm.assume(blockNumber > 0);
        vm.roll(blockNumber);
        vm.assume(timestamp > 0);
        vm.warp(timestamp);

        address caller = address(0x1234);
        uint256 exactValue = 10 ether;

        vm.deal(caller, exactValue);
        vm.prank(caller);
        (bool success,) = address(c).call{value: exactValue}("");
        assertTrue(success);

        if (blockNumber % 15 == 0) {
            assertTrue(address(c).balance == 0);
        }
    }
}
